/// Type of file.
#[derive(Clone, Copy, FromPrimitive, ToPrimitive)]
pub enum Type {
    /// Regular file.
    Regular = 1,
    /// Directory.
    Directory = 2,
    /// Block special device file.
    BlockDevice = 3,
    /// Character special device file.
    CharacterDevice = 4,
    /// Symbolic link.
    Symlink = 5,
    /// Socket file.
    Socket = 6,
    /// Named pipe.
    Fifo = 7,
}
